function ctx0(){return 0;}
function topKey(c){
var t=c.tr,best='np',bv= -1;
[['np',t.np],['fc',t.impulse],['cold',t.cold],['ac',t.ac],['cp',t.cp]].forEach(function(x){if(x[1]>bv){bv=x[1];best=x[0];}});
return best;
}
