function know(ctx,a,b){var pf=ctx.pair(a,b);pf.known=pf.known||{};return(pf.known[a.i]=pf.known[a.i]||{});}
function honneRule(ctx){return(ctx.rules||[]).filter(function(r){return r.k==='honne';})[0];}
