if(!pool.length)pool=NYAN.first;
var inc=(tk==='fc'||tk==='np'?1+ctx.rng.int(3):1+ctx.rng.int(2))*scaleOf(ctx,r);
var text=ctx.t(pickNew(ctx,pool),a,b);
